from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe');test=repo/'tests/test_application_answers.py'
base='2b57fff8ec673fef7fbeb6fe5ce00110a48a3f34'
def git(*a):return subprocess.run(['git',*a],cwd=repo,capture_output=True,text=True,check=True).stdout
if git('rev-parse','HEAD').strip()!=base or git('rev-parse','origin/main').strip()!=base:raise SystemExit('AUTHORITY_CHANGED')
entries=[x for x in git('status','--porcelain=v1','-z').split('\0') if x]
print('STATUS',repr(entries),flush=True)
allowed={'adapters/protocol.py','do-again.toml','do-again-policy.json','tests/test_application_answers.py'}
if any(x[3:] not in allowed for x in entries):raise SystemExit('UNEXPECTED_DIRTY')
original=git('show','HEAD:tests/test_application_answers.py')
current=test.read_text()
if not current.startswith(original) or current.count('def test_verified_global_answer_reused_across_distinct_job_plans_without_scope_leak(')!=1:raise SystemExit('ACCEPTANCE_NOT_PRESERVED')
def run(args,seconds):
 p=subprocess.Popen([str(repo/'.venv/bin/python'),'-m','pytest','-q','--maxfail=1','--tb=short',*args],cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try:o,e=p.communicate(timeout=seconds)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try:o,e=p.communicate(timeout=8)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate()
  print('TIMEOUT',args,o[-1800:],flush=True);raise SystemExit(124)
 print('RESULT',args,'EXIT',p.returncode,o[-3100:],e[-400:],flush=True)
 return p.returncode
if run(['tests/test_application_answers.py','tests/test_application_answer_resolution.py'],210):raise SystemExit('VALIDATION_FAILED')
subprocess.run(['git','add','--','tests/test_application_answers.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','test: verify cross-job reuse with exact scoped exclusion'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True,timeout=90)
print('VERIFIED_PUSH',git('rev-parse','HEAD').strip(),flush=True)
